#!/usr/bin/env python3
# Generated by `verdant-studio publish` from studio/src/Studio/Ops.lex.tex. Do not edit.
# app/src/Contract.lex.tex and model/strata.json each keep their entries on one long line, so two changes that
# each change entries there always conflict, whatever the entries. A change that only adds, removes or replaces
# entries is merged into main's file by entry instead: Contract's importmodule lines, dispatch routes and
# acceptance vectors, and the strata rows keyed by path (VS-05). Anything else is left to git apply.
#   merge BASE NEW MAIN PATH  prints NEW's entry changes merged into MAIN, or exits 1 when NEW changes more.
#   patch FILE                merges each of the two files a patch changes that way, and leaves the rest in FILE.
import json, os, re, subprocess, sys, tempfile
CONTRACT = 'app/src/Contract.lex.tex'
STRATA = 'model/strata.json'
NIL = '(nil Foundation.View.Text.V1.Model::AcceptanceVector)'
ROUTE = re.compile(r'[(]if [(]routed value (0x[0-9a-f]+)[)] then [(][A-Za-z0-9_.]+::[A-Za-z0-9_]+ [(]routedValue value \1[)][)] else ')
VECTOR = re.compile(r'[(]cons [(]record Foundation[.]View[.]Text[.]V1[.]Model::AcceptanceVector [{]request := 0x[0-9a-f]*, response := 0x[0-9a-f]*[}][)] ')
IMPORT = re.compile(r'(?m)^[\\]importmodule[{][^}]+[}]$')

def entries(text):
    return IMPORT.findall(text), [m.group(0) for m in ROUTE.finditer(text)], VECTOR.findall(text)

def dispatch_line(text):
    at = text.index('body: ', text.index('name: dispatch')) + 6
    return at, text.index(chr(10), at)

def skeleton(text):
    text = re.sub('[' + chr(10) + ']+', chr(10), IMPORT.sub('', ROUTE.sub('', VECTOR.sub('', text))))
    at, end = dispatch_line(text)
    line = text[at:end].rstrip(',').rstrip(')')
    text = text[:at] + line + text[end:]
    n = text.index(NIL) + len(NIL)
    return text[:n] + text[n:].lstrip(')')

def drop(text, gone):
    for entry in gone:
        text = text.replace(entry, '', 1) if not entry.startswith(chr(92)) else text.replace(entry + chr(10), '', 1)
    return text

def edit_contract(text, removed, added):
    imports, routes, vectors = added
    at, end = dispatch_line(text)
    line = drop(text[at:end], removed[1])
    tail = ',' if line.endswith(',') else ''
    line = line[:len(line) - len(tail)]
    line = ''.join(routes) + line[:len(line) - len(removed[1])] + ')' * len(routes) + tail
    text = drop(drop(text[:at] + line + text[end:], removed[2]), removed[0])
    if imports:
        last = list(IMPORT.finditer(text))[-1].end()
        text = text[:last] + ''.join(chr(10) + i for i in imports) + text[last:]
    n = text.index(NIL)
    after = text[n + len(NIL):]
    if not after.startswith(')' * len(removed[2])):
        raise ValueError('the vectors are not closed after their list')
    return text[:n] + ''.join(vectors) + NIL + ')' * len(vectors) + after[len(removed[2]):]

def merge_contract(base, new, main):
    if skeleton(base) != skeleton(new) or skeleton(base) != skeleton(main):
        return None
    b, n, m = entries(base), entries(new), entries(main)
    removed = [[e for e in old if e not in now and e in have] for old, now, have in zip(b, n, m)]
    added = [[e for e in now if e not in old and e not in have] for old, now, have in zip(b, n, m)]
    return edit_contract(main, removed, added)

def merge_strata(base, new, main):
    b, n, m = json.loads(base), json.loads(new), json.loads(main)
    kept = [r for r in m if r in n or r not in b]
    have = set(r['path'] for r in kept)
    rows = kept + [r for r in n if r not in b and r['path'] not in have]
    for ascii in (True, False):
        if json.dumps(m, separators=(',', ':'), ensure_ascii=ascii) + chr(10) == main:
            return json.dumps(rows, separators=(',', ':'), ensure_ascii=ascii) + chr(10)
    return None

def merge(base, new, main, path):
    return merge_contract(base, new, main) if path == CONTRACT else merge_strata(base, new, main)

def blob(sha):
    got = subprocess.run(['git', 'cat-file', '-p', sha], capture_output=True, text=True)
    if got.returncode == 0:
        return got.stdout
    return subprocess.run(['gh', 'api', '-H', 'Accept: application/vnd.github.raw', 'repos/' + os.environ['GITHUB_REPOSITORY'] + chr(47) + 'git/blobs/' + sha], capture_output=True, text=True, check=True).stdout

def changed(path, base, section):
    with tempfile.TemporaryDirectory() as work:
        subprocess.run(['git', 'init', '-q', work], check=True)
        os.makedirs(os.path.join(work, os.path.dirname(path)), exist_ok=True)
        open(os.path.join(work, path), 'w').write(base)
        subprocess.run(['git', 'apply', '-'], cwd=work, input=section, text=True, check=True)
        return open(os.path.join(work, path)).read()

def patch(name):
    text = open(name).read()
    parts = re.split('(?m)^(?=diff --git )', text)
    kept = [parts[0]]
    for section in parts[1:]:
        path = section.split(chr(10), 1)[0].split(' ')[-1][2:]
        index = re.search('(?m)^index ([0-9a-f]{40})[.][.]', section)
        merged = None
        if path in (CONTRACT, STRATA) and index:
            try:
                base = blob(index.group(1))
                merged = merge(base, changed(path, base, section), open(path).read(), path)
            except (OSError, ValueError, KeyError, subprocess.CalledProcessError) as failure:
                print('::warning::' + path + ' is left to git apply: ' + str(failure).splitlines()[0])
        if merged is None:
            kept.append(section)
        else:
            open(path, 'w').write(merged)
            print('::notice::merged the entries this change adds to ' + path + ' into main by entry')
    open(name, 'w').write(''.join(kept))

if sys.argv[1] == 'merge':
    merged = merge(*[open(p).read() for p in sys.argv[2:5]], sys.argv[5])
    if merged is None:
        sys.exit(1)
    sys.stdout.write(merged)
else:
    patch(sys.argv[2])
